css:
.zurielsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2118;
    background: linear-gradient(180deg, #fbf6ec 0%, #f4ead7 100%);
    border-radius: 18px;
}

.zurielsim-container * {
    box-sizing: border-box;
}

.zurielsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f7a4d 0%, #14603c 48%, #b5421f 100%);
    color: #fff8ec;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0e4a2d;
    box-shadow: 0 12px 30px rgba(31, 30, 18, 0.28);
}

.zurielsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #fffaf0;
}

.zurielsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffe2b0;
    background: rgba(255, 200, 120, 0.16);
    border: 1px solid rgba(255, 200, 120, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.zurielsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.58;
    color: #fbecd6;
}

.zurielsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b5a44;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.zurielsim-period-counter #currentDay,
.zurielsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14603c;
}

.zurielsim-round-name {
    background: rgba(20, 96, 60, 0.12);
    color: #14603c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.zurielsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5421f;
    background: rgba(181, 66, 31, 0.10);
    border: 1px solid rgba(181, 66, 31, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.zurielsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.zurielsim-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e7d8bd;
    box-shadow: 0 6px 16px rgba(75, 55, 25, 0.10);
    border-top: 4px solid #c9a76a;
}

.zurielsim-card-rep { border-top-color: #1f7a4d; }
.zurielsim-card-coh { border-top-color: #2f6fb0; }
.zurielsim-card-sales { border-top-color: #d98a1f; }
.zurielsim-card-sov { border-top-color: #b5421f; }

.zurielsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7a60;
}

.zurielsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b2118;
    font-variant-numeric: tabular-nums;
}

.zurielsim-card-rep .zurielsim-value { color: #1f7a4d; }
.zurielsim-card-coh .zurielsim-value { color: #2f6fb0; }
.zurielsim-card-sales .zurielsim-value { color: #c0731a; }
.zurielsim-card-sov .zurielsim-value { color: #b5421f; }

.zurielsim-sublabel {
    font-size: 0.76rem;
    color: #9a8a6f;
    line-height: 1.35;
}

/* The reputation tracker is the hero KPI — emphasise state. */
.zurielsim-card-rep { box-shadow: 0 8px 22px rgba(31, 122, 77, 0.16); }
.zurielsim-rep-strong { border-top-color: #1f7a4d; }
.zurielsim-rep-strong .zurielsim-value { color: #1f7a4d; }
.zurielsim-rep-weak { border-top-color: #b5421f; }
.zurielsim-rep-weak .zurielsim-value { color: #b5421f; }

.zurielsim-sales-positive .zurielsim-value { color: #1f7a4d; }
.zurielsim-sales-negative .zurielsim-value { color: #b5421f; }

.zurielsim-sov-high { border-top-color: #b5421f; }
.zurielsim-sov-high .zurielsim-value { color: #b5421f; }
.zurielsim-sov-low { border-top-color: #1f7a4d; }
.zurielsim-sov-low .zurielsim-value { color: #1f7a4d; }

.zurielsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf8;
    border: 1px solid #e7d8bd;
    color: #4a3c28;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.zurielsim-budget-bar #budgetDisplay {
    font-size: 1.06rem;
    letter-spacing: 0.3px;
    color: #14603c;
}

.zurielsim-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #b5421f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(75, 55, 25, 0.10);
}

.zurielsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.zurielsim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #14603c;
    margin-bottom: 6px;
}

.zurielsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #3c3024;
}

.zurielsim-briefing-text strong { color: #b5421f; }
.zurielsim-briefing-text em { color: #14603c; font-style: italic; }

.zurielsim-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e7d8bd;
    box-shadow: 0 6px 16px rgba(75, 55, 25, 0.10);
}

.zurielsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b2118;
    border-bottom: 2px solid #ecdcc0;
    padding-bottom: 8px;
}

.zurielsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a3c28;
    margin: 14px 0 6px;
}

.zurielsim-container select,
.zurielsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c39c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf8;
    color: #2b2118;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.zurielsim-container select:focus,
.zurielsim-container input[type="number"]:focus {
    outline: none;
    border-color: #1f7a4d;
    box-shadow: 0 0 0 3px rgba(31, 122, 77, 0.16);
}

.zurielsim-container select option {
    background-color: #fffdf8;
    color: #2b2118;
}

.zurielsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f7a4d;
}

.zurielsim-range-readout,
.zurielsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b5a44;
    margin-top: 4px;
}

.zurielsim-range-readout span:last-child,
.zurielsim-alloc-readout span:nth-child(2) {
    color: #14603c;
    font-weight: 800;
}

.zurielsim-hint {
    font-size: 0.8rem;
    color: #9a8a6f;
    margin-top: 4px;
    line-height: 1.42;
}

.zurielsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.zurielsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f8efdd;
    border: 1px solid #e3d2b2;
    border-radius: 9px;
    padding: 8px 12px;
}

.zurielsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #4a3c28;
}

.zurielsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.zurielsim-lab {
    background: #fff3e2;
    border: 1px dashed #d98a1f;
    color: #8a4a12;
    border-radius: 10px;
    padding: 12px 14px;
    font-size: 0.92rem;
    font-weight: 700;
    line-height: 1.5;
    margin-bottom: 6px;
}

.zurielsim-lab.zurielsim-lab-clean {
    background: #eaf6ef;
    border-color: #1f7a4d;
    color: #14603c;
}

.zurielsim-lab.zurielsim-lab-breach {
    background: #fbeae3;
    border-color: #b5421f;
    color: #8a3015;
}

.zurielsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.zurielsim-container .btn-primary {
    background: linear-gradient(135deg, #14603c 0%, #1f7a4d 100%);
    border: none;
    color: #fff8ec;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(20, 96, 60, 0.32);
}

.zurielsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.zurielsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c39c;
    color: #6b5a44;
    background: transparent;
}

.zurielsim-coach {
    background: linear-gradient(135deg, #2b2118 0%, #3a2c1c 100%);
    color: #f3e6cf;
    border: 1px solid #4a3829;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 22, 12, 0.28);
}

.zurielsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffc46b;
    margin-bottom: 8px;
}

.zurielsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.zurielsim-coach-body strong { color: #ffc46b; }
.zurielsim-coach-body em { color: #7fd6a3; font-style: italic; }

.zurielsim-history,
.zurielsim-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e7d8bd;
    box-shadow: 0 6px 16px rgba(75, 55, 25, 0.10);
}

.zurielsim-history h3,
.zurielsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2118;
}

.zurielsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3c3024;
}

.zurielsim-container table#usfHistoryTable th {
    background: #14603c;
    color: #fff8ec;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #0e4a2d;
}

.zurielsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ecdcc0;
    color: #3c3024;
}

.zurielsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8efdd;
}

.zurielsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .zurielsim-container {
        padding: 14px;
    }
    .zurielsim-header h1 {
        font-size: 1.75rem;
    }
    .zurielsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .zurielsim-value {
        font-size: 2.05rem;
    }
    .zurielsim-clock {
        margin-left: 0;
    }
    .zurielsim-period-counter {
        font-size: 0.88rem;
    }
    .zurielsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .zurielsim-alloc-row {
        flex-wrap: wrap;
    }
    .zurielsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .zurielsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, zurielsim) ---- */
.zurielsim-completion { padding: 8px 4px 4px; }
.zurielsim-cm-head { text-align: center; margin-bottom: 16px; }
.zurielsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a4d; }
.zurielsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #57a37e; }
.zurielsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #24303a; }
.zurielsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.zurielsim-cm-yes { background: rgba(31,122,77,0.14); color: #1a6b43; border: 1px solid rgba(31,122,77,0.5); }
.zurielsim-cm-no { background: rgba(181,66,31,0.12); color: #a53f1c; border: 1px solid rgba(181,66,31,0.45); }
.zurielsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.zurielsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(47,111,176,0.08); border: 1px solid rgba(47,111,176,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.zurielsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f6fb0; }
.zurielsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #6a7683; text-transform: uppercase; letter-spacing: 0.03em; }
.zurielsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #24303a; }
.zurielsim-cm-insights { margin: 0; padding-left: 20px; }
.zurielsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #384450; }

