(function() {
    'use strict';

    class ZurielAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Brand Under Pressure`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Zuriel Foods Plc.).
            this.BUDGET = 600;                 // NGN 600M contingency communications budget
            this.REP_PRE = 72;                 // pre-crisis reputation tracker
            this.REP_START = 51;               // 72h post-crisis tracker
            this.SALES_START = -22;            // week-one flagship sales decline (%)
            this.SOV_START = 89;               // negative share-of-voice (%)
            this.DELISTED = 31;                // % of modern-trade volume delisted

            // Concept truths.
            this.TRUE_NATURE = `coherence`;
            this.TRUE_GAP = `saydo`;
            this.TRUE_IDENTITY = `reframe`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rep: this.REP_START,        // corporate-reputation tracker (0–100, hero KPI)
                    coh: 30,                    // perceived say–do consistency (0–100)
                    sales: this.SALES_START,    // flagship sales vs pre-crisis (%)
                    sov: this.SOV_START,        // negative share-of-voice (%, lower better)
                    budgetUsed: 0,              // NGN M committed
                    sayDoOpen: true,            // the say–do gap is still open until R2 closes it
                    overClaimed: false,         // contested before results were in (premature defiance)
                    panicRebrand: false,        // abandoned heritage equity
                    labOutcome: ``,             // 'clean' | 'breach', revealed in R4
                    repHistory: [this.REP_START],
                    cohHistory: [30],
                    salesHistory: [this.SALES_START],
                    sovHistory: [this.SOV_START],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a click-through must not auto-win.
                state.decisions = {
                    nature: `prfire`,
                    gap: `image`,
                    split: 50,
                    identity: `hold`,
                    substance: `none`,
                    heritage: 50,
                    cert: 100,
                    micro: 100,
                    ceo: 100,
                    reengage: 100,
                    ads: 100,
                    front: 100,
                    tone: `reassuring`,
                    consistency: 50,
                    position: `victory`,
                    repair: 50,
                    pitch: `spin`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const na = document.getElementById(`natureInput`);
                const gp = document.getElementById(`gapInput`);
                const sp = document.getElementById(`splitInput`);
                if (na) decisions.nature = na.value;
                if (gp) decisions.gap = gp.value;
                if (sp) decisions.split = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.split) || decisions.split < 0 || decisions.split > 100) {
                    warn(`warn_split_range`); return false;
                }
            } else if (round === 2) {
                const id = document.getElementById(`identityInput`);
                const su = document.getElementById(`substanceInput`);
                const he = document.getElementById(`heritageInput`);
                if (id) decisions.identity = id.value;
                if (su) decisions.substance = su.value;
                if (he) decisions.heritage = parseInt(he.value, 10);
                if (!Number.isFinite(decisions.heritage) || decisions.heritage < 0 || decisions.heritage > 100) {
                    warn(`warn_heritage_range`); return false;
                }
            } else if (round === 3) {
                const ids = [`certInput`, `microInput`, `ceoInput`, `reengageInput`, `adsInput`, `frontInput`];
                const keys = [`cert`, `micro`, `ceo`, `reengage`, `ads`, `front`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const to = document.getElementById(`toneInput`);
                const cs = document.getElementById(`consistencyInput`);
                if (to) decisions.tone = to.value;
                if (cs) decisions.consistency = parseInt(cs.value, 10);
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total !== this.BUDGET) {
                    warn(`warn_alloc_total`); return false;
                }
                if (!Number.isFinite(decisions.consistency) || decisions.consistency < 0 || decisions.consistency > 100) {
                    warn(`warn_consistency_range`); return false;
                }
            } else if (round === 4) {
                const po = document.getElementById(`positionInput`);
                const re = document.getElementById(`repairInput`);
                const pi = document.getElementById(`pitchInput`);
                if (po) decisions.position = po.value;
                if (re) decisions.repair = parseInt(re.value, 10);
                if (pi) decisions.pitch = pi.value;
                if (!Number.isFinite(decisions.repair) || decisions.repair < 0 || decisions.repair > 100) {
                    warn(`warn_repair_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let repDelta = 0, cohDelta = 0, salesDelta = 0, sovDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: coherence failure, not a PR fire (Key Concept: identity–image–reputation).
                switch (d.nature) {
                    case `coherence`: cohDelta += 10; repDelta += 4; coachKey = `coach_r1_coherence`; break;
                    case `legal`: cohDelta -= 4; sovDelta += 4; ds.overClaimed = true; coachKey = `coach_r1_legal`; break;
                    case `sales`: cohDelta -= 2; coachKey = `coach_r1_sales`; break;
                    case `prfire`: cohDelta -= 5; repDelta -= 3; sovDelta += 4; coachKey = `coach_r1_prfire`; break;
                }

                // Which gap matters most — the say–do gap (Brand promise vs substance).
                switch (d.gap) {
                    case `saydo`: cohDelta += 10; repDelta += 3; if (d.nature === `coherence`) coachKey = `coach_r1_sharp`; break;
                    case `image`: cohDelta -= 2; sovDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r1_image` : coachKey; break;
                    case `none`: cohDelta -= 8; repDelta -= 3; sovDelta += 5; coachKey = `coach_r1_denial`; break;
                }

                // Substance vs perception split — the additive is real but permitted; ~55–70% substance is the honest read.
                if (d.split >= 50 && d.split <= 75) { cohDelta += 6; }
                else if (d.split < 25) { cohDelta -= 6; coachKey = `coach_r1_allperception`; }
                else if (d.split > 90) { cohDelta -= 3; }

                summaryKey = (d.nature === `coherence` && d.gap === `saydo`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Align the identity BEFORE communicating (Common Error 1: message before substance).
                switch (d.identity) {
                    case `reframe`: repDelta += 8; cohDelta += 10; sovDelta -= 6; coachKey = `coach_r2_reframe`; break;
                    case `defend`: repDelta += 6; cohDelta += 8; sovDelta -= 4; coachKey = `coach_r2_defend`; break;
                    case `hold`: repDelta -= 2; cohDelta -= 4; sovDelta += 4; ds.overClaimed = true; coachKey = `coach_r2_hold`; break;
                    case `reposition`: repDelta -= 4; cohDelta -= 6; sovDelta += 3; ds.panicRebrand = true; coachKey = `coach_r2_reposition`; break;
                }

                // Does substance change to close the say–do gap?
                switch (d.substance) {
                    case `reformulate`: ds.sayDoOpen = false; cohDelta += 10; repDelta += 4; salesDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_reformulate` : coachKey; break;
                    case `relabel`: ds.sayDoOpen = false; cohDelta += 6; repDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_relabel` : coachKey; break;
                    case `none`: cohDelta -= 8; sovDelta += 4; coachKey = `coach_r2_nochange`; break;
                }

                // Consistency with 35-year heritage (Common Error 5: panic repositioning).
                if (d.heritage >= 60) { repDelta += 6; cohDelta += 4; }
                else if (d.heritage <= 25) { repDelta -= 6; cohDelta -= 4; ds.panicRebrand = true; coachKey = `coach_r2_lowheritage`; }

                summaryKey = ((d.identity === `reframe` || d.identity === `defend`) && d.substance !== `none`) ? `sum_r2_good` :
                             (d.substance === `none` ? `sum_r2_message` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate the NGN 600M (Common Error 4: reach over credibility).
                const cert = d.cert, micro = d.micro, ceo = d.ceo, reengage = d.reengage, ads = d.ads, front = d.front;
                spend = cert + micro + ceo + reengage + ads + front;

                // Credibility/proof actions rebuild trust; reach (paid ads) only buys noise.
                // In a trust crisis, "who vouches for you matters more than how loud you are":
                // proof must drive reputation/consistency/SoV, and reach must NOT substitute for it.
                // Returns are per NGN 100M.
                const proof = (cert + micro) / 100;       // third-party cert + traceability microsite = proof
                const voice = ceo / 100;                  // credible spokesperson
                const shelf = reengage / 100;             // relist + narrative
                const reach = ads / 100;                  // paid corrective advertising (reach, low proof)
                const internal = front / 100;             // frontline coherence

                // Reputation is rebuilt by proof + a credible spokesperson; paid reach erodes it
                // (shouting "trust us" with no evidence reads as defensive spin).
                repDelta += proof * 9 + voice * 4 + shelf * 2 - reach * 2;
                cohDelta += proof * 4 + internal * 5 + voice * 2 - reach * 1;
                // Reach buys a little short-term shelf movement but proof/shelf carry sales.
                salesDelta += shelf * 6 + voice * 1 + reach * 0.5;
                // Proof + a credible voice turn the narrative; paid volume barely dents negative SoV,
                // and on a still-open gap it actively amplifies the negative conversation.
                sovDelta += -voice * 5 - shelf * 4 - proof * 6 - reach * 1;

                // Spending on a still-open say–do gap (Common Error 1) wastes the reach money:
                // you pay to broadcast the exact inconsistency that caused the crisis.
                if (ds.sayDoOpen) {
                    repDelta -= reach * 4;
                    sovDelta += reach * 4;
                    if (ads >= 250) coachKey = `coach_r3_opengap`;
                }

                // Reach-heavy with no proof bought (the classic, most-expensive trust-crisis error):
                // a hard penalty so it cannot out-score a proof-led plan.
                if ((cert + micro) <= 50 && ads >= 250) {
                    repDelta -= 16; cohDelta -= 8; sovDelta += 10;
                    coachKey = `coach_r3_reachonly`;
                } else if ((cert + micro) >= 250) {
                    coachKey = (coachKey === `coach_default`) ? `coach_r3_proof` : coachKey;
                }

                // Spokesperson tone (Common Error 2: premature defiance).
                switch (d.tone) {
                    case `contrite`: repDelta += 6; cohDelta += 4; sovDelta -= 4; break;
                    case `reassuring`: repDelta -= 2; sovDelta += 2; if (coachKey === `coach_default`) coachKey = `coach_r3_reassuring`; break;
                    case `defiant`: repDelta -= 6; cohDelta -= 5; sovDelta += 6; ds.overClaimed = true; coachKey = `coach_r3_defiant`; break;
                }

                // Stakeholder coherence (Common Error 3: divergent messages).
                if (d.consistency >= 60) { cohDelta += 8; repDelta += 3; sovDelta -= 3; }
                else if (d.consistency <= 25) { cohDelta -= 8; sovDelta += 6; coachKey = `coach_r3_incoherent`; }

                summaryKey = ((cert + micro) >= 250 && d.tone !== `defiant` && d.consistency >= 50) ? `sum_r3_good` :
                             (ads >= 300 && (cert + micro) <= 100 ? `sum_r3_reach` : `sum_r3_weak`);
            } else if (round === 4) {
                // Reveal the lab result via a deterministic coin-flip seeded from earlier choices,
                // so the same play always replays identically (state is restorable / serializable).
                if (!ds.labOutcome) {
                    const seed = (ds.coh + ds.rep + d.repair) % 2;
                    ds.labOutcome = seed === 0 ? `clean` : `breach`;
                }
                const clean = ds.labOutcome === `clean`;

                // Repositioning move (Common Error 5: panic repositioning; trust repair after vindication).
                switch (d.position) {
                    case `proof`: repDelta += 10; cohDelta += 8; sovDelta -= 8; salesDelta += 4; coachKey = `coach_r4_proof`; break;
                    case `heritage`: repDelta += 7; cohDelta += 5; sovDelta -= 5; salesDelta += 5; coachKey = `coach_r4_heritage`; break;
                    case `victory`: repDelta -= 4; cohDelta -= 4; sovDelta += 4; coachKey = `coach_r4_victory`; break;
                    case `pivot`: repDelta -= 6; cohDelta -= 6; sovDelta += 3; ds.panicRebrand = true; coachKey = `coach_r4_pivot`; break;
                }

                // The lab outcome modifies, but does not decide, the result —
                // a coherent strategy must hold under either reveal.
                if (clean) {
                    // Vindication helps only if you still repair trust (Decision Tree: "being right ≠ being trusted").
                    if (d.repair >= 50) { repDelta += 8; sovDelta -= 6; salesDelta += 4; }
                    else { repDelta += 1; sovDelta += 4; coachKey = `coach_r4_cleanstop`; }
                } else {
                    // Minor confirmed deviation: honesty so far is rewarded, prior over-claiming is punished hard.
                    if (ds.overClaimed) { repDelta -= 12; cohDelta -= 8; sovDelta += 10; coachKey = `coach_r4_breachlied`; }
                    else if (!ds.sayDoOpen) { repDelta += 4; cohDelta += 5; sovDelta -= 3; coachKey = `coach_r4_breachhonest`; }
                    else { repDelta -= 4; sovDelta += 4; }
                    salesDelta -= 3;
                }

                // The board-and-press pitch (Decision Tree: face the journalist with evidence).
                switch (d.pitch) {
                    case `evidence`: repDelta += 8; cohDelta += 6; sovDelta -= 10; if (d.position === `proof` || d.position === `heritage`) coachKey = `coach_r4_facedown`; break;
                    case `spin`: repDelta -= 4; cohDelta -= 4; sovDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r4_spin` : coachKey; break;
                    case `silence`: repDelta -= 6; sovDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_silence` : coachKey; break;
                }

                summaryKey = ((d.position === `proof` || d.position === `heritage`) && d.repair >= 50 && d.pitch === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the contingency budget is metered in R3 (the action menu).
            ds.budgetUsed = Math.min(this.BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas, clamped (rep/coh/sov 0–100; sales is a % around its start; lower sov is better).
            ds.rep = Math.max(0, Math.min(100, Math.round(ds.rep + repDelta)));
            ds.coh = Math.max(0, Math.min(100, Math.round(ds.coh + cohDelta)));
            ds.sales = Math.max(-40, Math.min(20, Math.round((ds.sales + salesDelta) * 10) / 10));
            ds.sov = Math.max(0, Math.min(100, Math.round(ds.sov + sovDelta)));

            ds.repHistory.push(ds.rep);
            ds.cohHistory.push(ds.coh);
            ds.salesHistory.push(ds.sales);
            ds.sovHistory.push(ds.sov);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                rep: ds.rep,
                repDelta: Math.round(repDelta),
                coh: ds.coh,
                cohDelta: Math.round(cohDelta),
                sales: ds.sales,
                salesDelta: Math.round(salesDelta * 10) / 10,
                sov: ds.sov,
                sovDelta: Math.round(sovDelta),
                budgetUsed: ds.budgetUsed,
                labOutcome: ds.labOutcome,
                sayDoOpen: ds.sayDoOpen,
                overClaimed: ds.overClaimed,
                panicRebrand: ds.panicRebrand,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtNaira(v) {
            // NGN in millions. English "₦600M"; Spanish "600 M₦" with comma decimals.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Math.round(v));
            if (lang === `es`) {
                return `${sign}${abs} M₦`;
            }
            return `${sign}₦${abs}M`;
        }

        _fmtPct(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const sign = n > 0 ? `+` : ``;
            return `${sign}${n}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`repDisplay`, `domainState.rep`, (v) => {
                const card = document.querySelector(`.zurielsim-card-rep`);
                if (card) {
                    card.classList.toggle(`zurielsim-rep-strong`, Number(v) >= 68);
                    card.classList.toggle(`zurielsim-rep-weak`, Number(v) <= 45);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`cohDisplay`, `domainState.coh`, (v) => Math.round(Number(v)));
            uiManager.bind(`salesDisplay`, `domainState.sales`, (v) => {
                const card = document.querySelector(`.zurielsim-card-sales`);
                if (card) {
                    card.classList.toggle(`zurielsim-sales-positive`, Number(v) >= 0);
                    card.classList.toggle(`zurielsim-sales-negative`, Number(v) < 0);
                }
                return self._fmtPct(Number(v));
            });
            uiManager.bind(`sovDisplay`, `domainState.sov`, (v) => {
                const card = document.querySelector(`.zurielsim-card-sov`);
                if (card) {
                    card.classList.toggle(`zurielsim-sov-high`, Number(v) >= 60);
                    card.classList.toggle(`zurielsim-sov-low`, Number(v) <= 30);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtNaira(Number(v)) + ` / ` + self._fmtNaira(self.BUDGET);
            });

            // R1 split slider readout.
            const sp = document.getElementById(`splitInput`);
            const spReadout = document.getElementById(`splitReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }

            // R2 heritage slider readout.
            const he = document.getElementById(`heritageInput`);
            const heReadout = document.getElementById(`heritageReadout`);
            if (he && heReadout) {
                heReadout.textContent = he.value;
                he.addEventListener(`input`, function() { heReadout.textContent = he.value; });
            }

            // R3 stakeholder consistency slider readout.
            const cs = document.getElementById(`consistencyInput`);
            const csReadout = document.getElementById(`consistencyReadout`);
            if (cs && csReadout) {
                csReadout.textContent = cs.value;
                cs.addEventListener(`input`, function() { csReadout.textContent = cs.value; });
            }

            // R4 repair slider readout.
            const re = document.getElementById(`repairInput`);
            const reReadout = document.getElementById(`repairReadout`);
            if (re && reReadout) {
                reReadout.textContent = re.value;
                re.addEventListener(`input`, function() { reReadout.textContent = re.value; });
            }

            // R3 budget live total (must hit NGN 600M).
            const allocIds = [`certInput`, `microInput`, `ceoInput`, `reengageInput`, `adsInput`, `frontInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.zurielsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.BUDGET) ? `#b5421f` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                zurielChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_rep`, `Reputation`),
                                data: [],
                                borderColor: `#1f7a4d`,
                                backgroundColor: `rgba(31,122,77,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#1f7a4d`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_coh`, `Consistency`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_sov`, `Negative SoV (lower better)`),
                                data: [],
                                borderColor: `#b5421f`,
                                backgroundColor: `rgba(181,66,31,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b5421f`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
