                            legend: { position: `bottom`, labels: { color: `#4a3c28`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8a7a60` }, grid: { color: `rgba(75,55,25,0.08)` },
                                title: { display: true, text: `0–100`, color: `#8a7a60` }
                            },
                            x: {
                                ticks: { color: `#8a7a60` }, grid: { color: `rgba(75,55,25,0.05)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#8a7a60` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.repHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                zurielChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.repHistory },
                        { data: ds.cohHistory },
                        { data: ds.sovHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const rep = Math.round(ds.rep);
            const coh = Math.round(ds.coh);
            const sales = Math.round(ds.sales * 10) / 10;
            const sov = Math.round(ds.sov);
            const salesScore = Math.max(0, Math.min(60, (sales + 40)));
            const composite = Math.round(
                rep * 0.34 + coh * 0.28 + (100 - sov) * 0.26 + salesScore * 0.20
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="zurielsim-cm-badge zurielsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="zurielsim-cm-badge zurielsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.panicRebrand) failBadge += ` <span class="zurielsim-cm-badge zurielsim-cm-no">` + T(`cm_rebrand`) + `</span>`;
            if (s.overClaimed) failBadge += ` <span class="zurielsim-cm-badge zurielsim-cm-no">` + T(`cm_overclaim`) + `</span>`;
            if (s.labOutcome === `breach`) failBadge += ` <span class="zurielsim-cm-badge zurielsim-cm-no">` + T(`cm_breach`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const fmtPct = (typeof this._fmtPct === `function`) ? this._fmtPct.bind(this) : function(v){ return v + `%`; };
            const metrics = ``
                + `<div class="zurielsim-cm-metric"><span class="zurielsim-cm-mv">` + Math.round(s.rep || 0) + `</span><span class="zurielsim-cm-ml">` + T(`cm_m_rep`) + `</span></div>`
                + `<div class="zurielsim-cm-metric"><span class="zurielsim-cm-mv">` + Math.round(s.coh || 0) + `</span><span class="zurielsim-cm-ml">` + T(`cm_m_coh`) + `</span></div>`
                + `<div class="zurielsim-cm-metric"><span class="zurielsim-cm-mv">` + fmtPct(Number(s.sales || 0)) + `</span><span class="zurielsim-cm-ml">` + T(`cm_m_sales`) + `</span></div>`
                + `<div class="zurielsim-cm-metric"><span class="zurielsim-cm-mv">` + Math.round(s.sov || 0) + `%</span><span class="zurielsim-cm-ml">` + T(`cm_m_sov`) + `</span></div>`;
            return ``
                + `<div class="zurielsim-completion">`
                +   `<div class="zurielsim-cm-head">`
                +     `<div class="zurielsim-cm-score">` + score + `<span class="zurielsim-cm-score-max">/100</span></div>`
                +     `<div class="zurielsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="zurielsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="zurielsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="zurielsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const rep = Math.round(ds.rep);
            const coh = Math.round(ds.coh);
            const sales = Math.round(ds.sales * 10) / 10;
            const sov = Math.round(ds.sov);

            // Composite: reputation, consistency, low negative SoV, plus a sales-recovery bonus
            // (normalised: -40%..+20% mapped to 0..60 then scaled).
            const composite = this._composite(ds);

            const recovered = rep >= 65 && sov <= 35;
            const coherent = coh >= 60;
            const commercial = sales >= -8;
            const exposed = ds.panicRebrand || sov >= 70 || (ds.overClaimed && ds.labOutcome === `breach`);

            let performanceKey = `grade_unrepaired`;
            if (recovered && coherent && commercial && composite >= 75) performanceKey = `grade_rebuilt`;
            else if (recovered && coherent) performanceKey = `grade_contained`;
            else if (exposed) performanceKey = `grade_expose`;
            else if (sales <= -25) performanceKey = `grade_shelflost`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (recovered && coherent && commercial) insights.push(window.mySimulation.t(`insight_rebuilt`));
            else if (exposed) insights.push(window.mySimulation.t(`insight_exposed`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.labOutcome === `breach`) insights.push(window.mySimulation.t(`insight_breach`));
            else if (ds.labOutcome === `clean`) insights.push(window.mySimulation.t(`insight_clean`));
            if (ds.sayDoOpen) insights.push(window.mySimulation.t(`insight_saydo`));
            if (ds.overClaimed) insights.push(window.mySimulation.t(`insight_overclaim`));
            if (ds.panicRebrand) insights.push(window.mySimulation.t(`insight_rebrand`));
            if (sales <= -20) insights.push(window.mySimulation.t(`insight_sales`));
            if (coh >= 65 && rep >= 65 && sov <= 30) insights.push(window.mySimulation.t(`insight_coherent`));

            return {
                rep: rep,
                coh: coh,
                sales: sales,
                sov: sov,
                recovered: recovered,
                coherent: coherent,
                commercial: commercial,
                exposed: exposed,
                labOutcome: ds.labOutcome,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (recovered && coherent && commercial && composite >= 75),
                panicRebrand: ds.panicRebrand,
                overClaimed: ds.overClaimed,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.sayDoOpen && state.currentPeriod >= 2) return window.mySimulation.t(`hint_saydo`);
            if (ds.overClaimed) return window.mySimulation.t(`hint_overclaim`);
            if (ds.panicRebrand) return window.mySimulation.t(`hint_rebrand`);
            if (ds.sov >= 70) return window.mySimulation.t(`hint_sov`);
            if (state.currentPeriod >= 3 && ds.coh < 40) return window.mySimulation.t(`hint_coh`);
            if (ds.rep >= 65 && ds.coh >= 60 && ds.sov <= 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.rep`, label: `Reputation`, i18nKey: `col_rep`, formatter: (v) => Math.round(v) },
                { key: `results.coh`, label: `Consistency`, i18nKey: `col_coh`, formatter: (v) => Math.round(v) },
                { key: `results.sales`, label: `Sales`, i18nKey: `col_sales`, formatter: (v) => self._fmtPct(Number(v)) },
                { key: `results.sov`, label: `Neg SoV`, i18nKey: `col_sov`, formatter: (v) => Math.round(v) + `%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            // Reveal the lab result line on entering Round 4.
            const labEl = document.getElementById(`labReveal`);
            const ds = state.domainState;
            if (labEl && idx === 3 && ds) {
                if (!ds.labOutcome) {
                    const seed = (ds.coh + ds.rep + (state.decisions ? state.decisions.repair : 50)) % 2;
                    ds.labOutcome = seed === 0 ? `clean` : `breach`;
                }
                labEl.classList.remove(`zurielsim-lab-clean`, `zurielsim-lab-breach`);
                if (ds.labOutcome === `clean`) {
                    labEl.classList.add(`zurielsim-lab-clean`);
                    labEl.innerHTML = t(`lab_clean`);
                } else {
                    labEl.classList.add(`zurielsim-lab-breach`);
                    labEl.innerHTML = t(`lab_breach`);
                }
            }

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

